describe('Multi-Step Form Progress Indicator', () => {
  beforeEach(() => {
    cy.visit('/multi-step-form');
  });

  it('should display progress indicator and update as user completes each step', () => {
    // Verify initial state: progress indicator shows 0%
    cy.get('[data-testid="progress-indicator"]').should('be.visible');
    cy.get('[data-testid="progress-indicator"]').should('have.css', 'width', '0%');

    // Intercept API call for first step
    cy.intercept('POST', '/api/step1').as('step1Request');

    // Complete first step
    cy.get('[data-testid="step1-form-input"]').type('John Doe');
    cy.get('[data-testid="step1-submit-button"]').click();

    // Wait for API response
    cy.wait('@step1Request');

    // Verify progress indicator updates to 25%
    cy.get('[data-testid="progress-indicator"]').should('have.css', 'width', '25%');

    // Intercept API call for second step
    cy.intercept('POST', '/api/step2').as('step2Request');

    // Complete second step
    cy.get('[data-testid="step2-form-input"]').type('jane.doe@example.com');
    cy.get('[data-testid="step2-submit-button"]').click();

    // Wait for API response
    cy.wait('@step2Request');

    // Verify progress indicator updates to 50%
    cy.get('[data-testid="progress-indicator"]').should('have.css', 'width', '50%');

    // Intercept API call for third step
    cy.intercept('POST', '/api/step3').as('step3Request');

    // Complete third step
    cy.get('[data-testid="step3-form-input"]').type('123-45-6789');
    cy.get('[data-testid="step3-submit-button"]').click();

    // Wait for API response
    cy.wait('@step3Request');

    // Verify progress indicator updates to 100%
    cy.get('[data-testid="progress-indicator"]').should('have.css', 'width', '100%');

    // Verify success message appears
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'Form submitted successfully');

    // Verify form is submitted
    cy.get('[data-testid="form-submission-status"]').should('contain', 'Submitted');
  });

  it('should display error message when form validation fails at any step', () => {
    // Intercept API call for first step
    cy.intercept('POST', '/api/step1').as('step1Request');

    // Attempt to complete first step with invalid data
    cy.get('[data-testid="step1-form-input"]').type('John');
    cy.get('[data-testid="step1-submit-button"]').click();

    // Wait for API response
    cy.wait('@step1Request');

    // Verify error message appears
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Please enter a full name');

    // Verify progress indicator does not update
    cy.get('[data-testid="progress-indicator"]').should('have.css', 'width', '0%');

    // Intercept API call for second step
    cy.intercept('POST', '/api/step2').as('step2Request');

    // Attempt to complete second step with invalid email
    cy.get('[data-testid="step2-form-input"]').type('invalid-email');
    cy.get('[data-testid="step2-submit-button"]').click();

    // Wait for API response
    cy.wait('@step2Request');

    // Verify error message appears again
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Please enter a valid email address');

    // Verify progress indicator remains at 25%
    cy.get('[data-testid="progress-indicator"]').should('have.css', 'width', '25%');

    // Intercept API call for third step
    cy.intercept('POST', '/api/step3').as('step3Request');

    // Attempt to complete third step with invalid SSN
    cy.get('[data-testid="step3-form-input"]').type('123-45-67899');
    cy.get('[data-testid="step3-submit-button"]').click();

    // Wait for API response
    cy.wait('@step3Request');

    // Verify error message appears for the third time
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Please enter a valid SSN');

    // Verify progress indicator remains at 50%
    cy.get('[data-testid="progress-indicator"]').should('have.css', 'width', '50%');
  });
});
